import{z as s,x as o,o as a,c as C,q as B,j as i,D as A,d as e,s as r,S as n,b as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"数学数据的合成","description":"","frontmatter":{"title":"数学数据的合成","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/synthetic-math-pipeline.md","filePath":"llm/synthetic-math-pipeline.md","lastUpdated":1791063341000}'),p={name:"llm/synthetic-math-pipeline.md"};function D(h,E,d,m,F,c){const l=o("Mermaid");return a(),C("div",null,[E[2]||(E[2]=B('<h1 id="数学数据的合成" tabindex="-1">数学数据的合成 <a class="header-anchor" href="#数学数据的合成" aria-label="Permalink to &quot;数学数据的合成&quot;">​</a></h1><div class="epigraph"><p>数学是合成数据的第一个主场：真值可以由程序裁决，于是生成可以放量、错误可以拦截——上限只剩验证器等价性的写法。</p><footer>—— 据 Yu 等 Meta-Math；Yuan 等 RFT；Lightman 等 Let&#39;s Verify Step by Step 整理</footer></div><p><a href="/llm/synthetic-dedup-contamination">上一课</a>收掉了通用管线的身份关卡，从本课起进入域合成。数学域的特别之处在验证器：答案对不对可以交给符号计算与等价检查，<a href="/llm/math-verifier-equivalence">验证器等价</a>课已写清「对」的判定本身是工程。本课写题与解从哪来——改写题面、拒绝采样造解、程序出题三条线——以及它们各自把哪类错误放进了数据。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三条线各有缺口。改写线：对已有题做答案保持或答案可追的变异（换数字、换情境、反向提问），题量指数上涨，但改写出的题可能无解、多解或与原答案脱钩——「题面改了答案没改」是最高产的事故。拒绝采样线：同一道题让模型采样多条推理链，只保留最终答案正确的，便宜且天然带链多样性；但答案对不等于推理对，凑答案、反推、蒙对都会混进来。程序出题线：从知识点模板生成题与标准答案，真值最干净，但表面分布窄，模板化风险在谱系课已点名。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三条线各配一个闸。改写线：以答案为锚——先定答案再生成题面，或改写后重算答案，重算不一致即丢弃；变异算子要带「答案可验证」约束，无解与多解由验证器甄别，不是由教师自评。拒绝采样线：组采样加答案核对，<a href="/llm/rejection-sampling-rft">拒绝采样与 RFT</a>已讲循环本体；合成语境的增量是链级过滤——同一题保留多条不同链是资产，但链之间要过一致性：同一题的多条链给出同一答案才可信，只对一次的链降权。程序出题线：模板参数采样生成题，答案由符号系统重算而不是模板里存字符串；题型覆盖用知识点网格审计，防止参数采样只在浅层打转。</p><p>步级监督是可选的第四站：答案正确的链，其步骤对错仍未知。<a href="/llm/lightman-prm">过程奖励</a>课讲过人工步标的成本，Math-Shepherd 式的自动步标用蒙特卡洛完成度估计每一步的价值——把 PRM 推到规模的是步标的自动化，不是 PRM 本身。</p>',8)),(a(),i(n,null,{default:A(()=>[r(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%7B%22%E9%A2%98%E6%BA%90%E4%B8%89%E7%BA%BF%22%7D%0A%20%20SRC%20--%3E%7C%E6%94%B9%E5%86%99%E9%A2%98%E9%9D%A2%7C%20ANS%5B%22%E7%AD%94%E6%A1%88%E9%94%9A%E5%AE%9A%E4%B8%8E%E9%87%8D%E7%AE%97%22%5D%0A%20%20SRC%20--%3E%7C%E6%8B%92%E7%BB%9D%E9%87%87%E6%A0%B7%7C%20SAMP%5B%22%E7%BB%84%E9%87%87%E6%A0%B7%E5%A4%9A%E6%9D%A1%E9%93%BE%22%5D%0A%20%20SRC%20--%3E%7C%E7%A8%8B%E5%BA%8F%E5%87%BA%E9%A2%98%7C%20TPL%5B%22%E6%A8%A1%E6%9D%BF%E5%8F%82%E6%95%B0%E5%8A%A0%E7%AC%A6%E5%8F%B7%E9%87%8D%E7%AE%97%22%5D%0A%20%20ANS%20--%3E%20CHK%7B%22%E7%AD%94%E6%A1%88%E4%B8%80%E8%87%B4%EF%BC%9F%22%7D%0A%20%20TPL%20--%3E%20CHK%0A%20%20CHK%20--%3E%7C%E5%90%A6%7C%20DROP%5B%22%E4%B8%A2%E5%BC%83%22%5D%0A%20%20CHK%20--%3E%7C%E6%98%AF%7C%20SAMP%0A%20%20SAMP%20--%3E%20MAJ%7B%22%E5%A4%9A%E6%95%B0%E9%93%BE%E5%90%8C%E7%AD%94%E6%A1%88%EF%BC%9F%22%7D%0A%20%20MAJ%20--%3E%7C%E5%90%A6%7C%20DROP%0A%20%20MAJ%20--%3E%7C%E6%98%AF%7C%20CHAIN%5B%22%E4%BF%9D%E7%95%99%E9%93%BE%22%5D%0A%20%20CHAIN%20--%3E%20PRM%5B%22%E5%8F%AF%E9%80%89%EF%BC%9A%E8%87%AA%E5%8A%A8%E6%AD%A5%E6%A0%87%22%5D%0A%20%20PRM%20--%3E%20POOL%5B%22%E5%85%A5%E5%BA%93%EF%BC%8C%E5%B8%A6%E9%A2%98%E5%9E%8B%E4%B8%8E%E9%9A%BE%E5%BA%A6%E6%A0%87%E7%AD%BE%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=t("p",null,"为什么数学能放量而开放域不能：拦截率决定放量上限。数学的拦截是程序级的，每一条入库样本都过了可复算的检查；开放域的拦截靠裁判，检查本身有偏。链级过滤的机制在于分离「答案误差」与「推理误差」：只看最终答案时，假推理与真推理同样得分，训练把「说得像对的」而不是「对的」放大；多链一致性与步标是把两个误差源拆开的手段——前者投票压随机误差，后者逐步定位系统误差。改写线的机制风险则是分布塌缩到原题邻域：改写保留答案结构，也保留了原题的解法偏置，题量大不等于覆盖宽，覆盖要交给多样性度量课的网格审计。",-1)),(a(),i(n,null,{default:A(()=>[r(l,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%90%8C%E4%B8%80%E9%81%93%E9%A2%98%22%5D%20--%3E%20C1%5B%22%E9%93%BE1%EF%BC%9A%E7%AD%94%E6%A1%88A%22%5D%0A%20%20Q%20--%3E%20C2%5B%22%E9%93%BE2%EF%BC%9A%E7%AD%94%E6%A1%88A%22%5D%0A%20%20Q%20--%3E%20C3%5B%22%E9%93%BE3%EF%BC%9A%E7%AD%94%E6%A1%88A%22%5D%0A%20%20Q%20--%3E%20C4%5B%22%E9%93%BE4%EF%BC%9A%E7%AD%94%E6%A1%88B%22%5D%0A%20%20C4%20--%3E%20V2%5B%22%E5%B0%91%E6%95%B0%E7%A5%A8%EF%BC%9A%E9%99%8D%E6%9D%83%E6%88%96%E4%B8%A2%E5%BC%83%22%5D%0A%20%20C1%20--%3E%20V1%5B%223%E7%A5%A8%E5%A4%9A%E6%95%B0%EF%BC%9A%E7%AD%94%E6%A1%88A%E5%8F%AF%E4%BF%A1%22%5D%0A%20%20C2%20--%3E%20V1%0A%20%20C3%20--%3E%20V1%0A%20%20V1%20--%3E%20S%5B%22%E9%80%90%E6%AD%A5%E5%A4%8D%E6%A0%B8%EF%BC%9A%E8%87%AA%E5%8A%A8%E6%AD%A5%E6%A0%87%E4%BC%B0%E5%AE%8C%E6%88%90%E5%BA%A6%22%5D%0A%20%20S%20--%3E%20OK%5B%22%E7%9C%9F%E6%8E%A8%E7%90%86%EF%BC%9A%E6%AD%A5%E4%B8%8E%E7%AD%94%E9%83%BD%E5%AF%B9%EF%BC%8C%E9%AB%98%E5%88%86%E5%85%A5%E5%BA%93%22%5D%0A%20%20S%20--%3E%20BAD%5B%22%E5%81%87%E6%8E%A8%E7%90%86%EF%BC%9A%E7%AD%94%E6%A1%88%E5%AF%B9%E4%BD%86%E6%AD%A5%E9%AA%A4%E5%BC%B1%EF%BC%8C%E9%99%8D%E6%9D%83%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=B('<p><span class="marginnote">蒙特卡洛完成度估计可以翻译成「从这里出发还有多少胜算」：把某一步之后的推理随机续写 8 次，最终答对 6 次，这一步就得 0.75 分。它用胜算代替人工标注给每一步打分，Math-Shepherd 靠这一手把过程奖励推到了规模。</span></p><p><span class="marginnote">Meta-Math 的答案是条件改写：以「原题加答案」为条件生成新题面，把答案变成生成约束而不是事后核对。这一步让改写的有效率大幅上升——约束放在生成侧，永远比放在过滤侧便宜。</span></p><p><span class="marginnote">多链一致性给个数字实例：同一题采 8 条链，6 条给出答案 A、2 条给出 B，一致率 75%，达到阈值就收 A；若 8 条链答案五花八门，说明题目多半超出模型当前能力，整题丢弃，而不是硬凑一个两票对一票的「多数」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>验证器等价是全线的天花板：数值等价、符号等价、格式归一没写对，拦截率就失真——好样本被丢，坏样本被留。<span class="marginnote">初学者容易以为改写出的一万道题等于一万道不同的题。实际上改写大多落在原题邻域：换个人名、换个数字，解法套路一模一样，模型刷再多也只是背熟同一类模板，覆盖要靠知识点网格审计兜底。</span>证明题只有终结判定没有过程真值，拒绝采样只能收「证完了」的链，步级监督退化成启发式；几何与含图题的验证器覆盖更薄。改写与程序出题产出的「难」是结构难，不等于对学生难，入库时带的难度标签要留给难度分级课用通过率重标。最后，数学合成的产出常被蒸馏管线二次消费，链的长短与文体要按学生口径再过滤，这是<a href="/llm/reasoning-distill-small">推理蒸馏到小模型</a>的辖区，本课不越界。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三条题源线：答案锚定改写、组采样拒绝过滤、模板加符号重算。</li><li>答案对不等于推理对：多链一致性与步级监督拆开两类误差。</li><li>拦截率是程序级的，数学才能放量；验证器等价性是全线天花板。</li><li>步标自动化（蒙特卡洛完成度）把 PRM 推到规模。</li><li>改写保结构也保偏置，题量不等于覆盖。</li><li>出处：Yu 等 Meta-Math 2023；Yuan 等 RFT 2023；Lightman 等 2023；Wang 等 Math-Shepherd 2023。</li></ul>',7))])}const S=s(p,[["render",D]]);export{u as __pageData,S as default};
